messages.content:
Berikut manifest game klasifikasi hewan vertebrata dengan mekanik Ludic Learning dan tema Clean Modern. Saya menambahkan paus dan lumba-lumba sebagai item mamalia untuk meluruskan miskonsepsi utama.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "klasifikasi-satwa-run", title: "Klasifikasi Satwa Run", seed: "satwa-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Biologi - Klasifikasi Hewan Vertebrata",
    concept: "Mengelompokkan hewan ke dalam kelas Mamalia, Reptil, dan Ikan berdasarkan cirinya",
    objectives: [
      "Membedakan hewan mamalia, reptil, dan ikan",
      "Meluruskan miskonsepsi bahwa paus dan lumba-lumba adalah ikan"
    ],
    misconceptions: [
      "Paus dan lumba-lumba dianggap ikan karena hidup di air"
    ],
    mode: "category",
    categories: [
      { id: "mamalia", label: "Mamalia", color: "#2F80ED" },
      { id: "reptil",  label: "Reptil",  color: "#3FA34D" },
      { id: "ikan",    label: "Ikan",    color: "#00A3C4" }
    ],
    items: [
      { id: "lumba-lumba", label: "Lumba-lumba", category: "mamalia", explain: "Bernapas dengan paru-paru dan menyusui anaknya; mamalia, bukan ikan." },
      { id: "paus",        label: "Paus",        category: "mamalia", explain: "Hidup di air tapi bernapas dengan paru-paru dan melahirkan; mamalia." },
      { id: "kelelawar",   label: "Kelelawar",   category: "mamalia", explain: "Berbulu, melahirkan, dan menyusui; mamalia meski bisa terbang." },
      { id: "kucing",      label: "Kucing",      category: "mamalia", explain: "Berbulu, melahirkan, dan menyusui anaknya; mamalia." },
      { id: "kadal",       label: "Kadal",       category: "reptil",  explain: "Bersisik, berdarah dingin, dan bertelur; reptil." },
      { id: "ular",        label: "Ular",        category: "reptil",  explain: "Bertubuh bersisik dan bertelur; reptil walau tanpa kaki." },
      { id: "penyu",       label: "Penyu",       category: "reptil",  explain: "Bercangkang keras, bertelur di pasir; reptil." },
      { id: "hiu",         label: "Hiu",         category: "ikan",    explain: "Bernapas dengan insang dan bertelur atau melahirkan; ikan." },
      { id: "salmon",      label: "Salmon",      category: "ikan",    explain: "Bernapas dengan insang dan bertelur; ikan." },
      { id: "kuda-laut",   label: "Kuda laut",   category: "ikan",    explain: "Bernapas dengan insang dan bertelur; ikan walau bentuknya unik." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game ini mengajak pemain mengklasifikasikan hewan mamalia, reptil, dan ikan sambil menghindari rintangan, dengan paus dan lumba-lumba sebagai item kunci untuk meluruskan miskonsepsi. Asumsi penting: rintangan dibuat sederhana (batu dan genangan) agar fokus belajar tetap pada klasifikasi hewan.
